import assert from "node:assert/strict";
import { after, before, describe, it } from "node:test";
import { openDatabase } from "../src/db.ts";
import { listTasks } from "../src/tasks.ts";
import { newDbPath, startServer, type Running } from "./helpers/server.ts";

interface Task {
  id: number;
  title: string;
  created_at: string;
}

async function post(server: Running, title: string): Promise<void> {
  const response = await fetch(`${server.baseUrl}/api/tasks`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title }),
  });
  assert.equal(response.status, 201);
}

async function get(server: Running): Promise<Response> {
  return fetch(`${server.baseUrl}/api/tasks`);
}

describe("SL-008 list open tasks newest first, with an empty state", () => {
  describe("AC-1: tasks added as A, B, C", () => {
    let server: Running;
    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-1: the list reads C, B, A", async () => {
      for (const title of ["A", "B", "C"]) {
        await post(server, title);
        await new Promise((resolve) => setTimeout(resolve, 5));
      }
      const { tasks } = (await (await get(server)).json()) as { tasks: Task[] };
      assert.deepEqual(
        tasks.map((t) => t.title),
        ["C", "B", "A"],
      );
    });
  });

  describe("AC-2: tasks created within the same instant", () => {
    it("AC-2: the one saved last is listed first, every time", () => {
      const db = openDatabase(":memory:");
      const instant = "2026-01-01T00:00:00.000Z";
      for (const title of ["first", "second", "third"]) {
        db.all(
          "INSERT INTO tasks (title, created_at, updated_at) VALUES (?, ?, ?)",
          title,
          instant,
          instant,
        );
      }
      for (let run = 0; run < 5; run++) {
        assert.deepEqual(
          listTasks(db).map((t) => t.title),
          ["third", "second", "first"],
        );
      }
    });

    it("AC-2: creation time outranks the id", () => {
      const db = openDatabase(":memory:");
      const insert = (title: string, at: string) =>
        db.all("INSERT INTO tasks (title, created_at, updated_at) VALUES (?, ?, ?)", title, at, at);
      insert("newer", "2026-01-02T00:00:00.000Z");
      insert("older", "2026-01-01T00:00:00.000Z");
      assert.deepEqual(
        listTasks(db).map((t) => t.title),
        ["newer", "older"],
      );
    });

    it("AC-2: tasks posted back to back come back in reverse order", async () => {
      const server = await startServer();
      try {
        const titles = Array.from({ length: 30 }, (_, i) => `task ${i}`);
        for (const title of titles) await post(server, title);
        const { tasks } = (await (await get(server)).json()) as { tasks: Task[] };
        assert.deepEqual(
          tasks.map((t) => t.title),
          titles.reverse(),
        );
      } finally {
        await server.stop();
      }
    });
  });

  describe("AC-3: an empty list", () => {
    let server: Running;
    let html: string;
    let script: string;
    before(async () => {
      server = await startServer();
      html = await (await fetch(`${server.baseUrl}/`)).text();
      script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-3: the API answers 200 with an empty list", async () => {
      const response = await get(server);
      assert.equal(response.status, 200);
      assert.deepEqual(await response.json(), { tasks: [] });
    });

    it("AC-3: the page has an empty-state element that the script shows only without tasks", () => {
      assert.match(html, /<[a-z]+[^>]+id=["']empty-state["']/);
      assert.match(script, /empty-state/);
      assert.match(script, /\.hidden\s*=\s*tasks\.length\s*>\s*0/);
    });
  });

  describe("AC-4: about 1000 stored tasks", () => {
    const dbPath = newDbPath();
    let server: Running;
    before(async () => {
      const db = openDatabase(dbPath);
      for (let i = 0; i < 1000; i++) {
        const at = new Date(Date.UTC(2026, 0, 1) + i * 1000).toISOString();
        db.all(
          "INSERT INTO tasks (title, created_at, updated_at) VALUES (?, ?, ?)",
          `Typical task number ${i}: pick up the parcel and send the report`,
          at,
          at,
        );
      }
      server = await startServer(dbPath);
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-4: p95 of 20 sequential requests is under 100 ms and the body under 400000 bytes", async () => {
      const times: number[] = [];
      for (let i = 0; i < 20; i++) {
        const start = performance.now();
        const response = await get(server);
        const body = await response.arrayBuffer();
        times.push(performance.now() - start);
        assert.equal(response.status, 200);
        assert.ok(body.byteLength < 400000, `body is ${body.byteLength} bytes`);
        const { tasks } = JSON.parse(new TextDecoder().decode(body)) as { tasks: Task[] };
        assert.equal(tasks.length, 1000);
      }
      times.sort((a, b) => a - b);
      const p95 = times[Math.ceil(times.length * 0.95) - 1];
      assert.ok(p95 < 100, `p95 was ${p95.toFixed(1)} ms`);
    });
  });
});
